query:
query DeployedProvenance($package: SuiAddress!, $original: SuiAddress!) {
 checkpoint { sequenceNumber timestamp }
 deployed: object(address: $package) { address version digest owner { __typename } previousTransaction { digest sender { address } effects { status checkpoint { sequenceNumber timestamp } } transactionJson } asMovePackage {
  address version linkage { originalId upgradedId version } typeOrigins { module struct definingId }
  modules(first: 50) { nodes { name fileFormatVersion bytes } pageInfo { hasNextPage endCursor } }
  packageVersionsBefore(first: 20) { nodes { address version digest previousTransaction { digest effects { checkpoint { sequenceNumber timestamp } } } } pageInfo { hasNextPage endCursor } }
 } }
 original: object(address: $original) { address version digest previousTransaction { digest effects { status checkpoint { sequenceNumber timestamp } } } }
}
